/**
 * 場景觸發處理
 * Topic: homeassistant/scene/{scene_name}/activate
 * Payload: "activate"
 */

const parts = String(msg.topic || "").split("/");

// homeassistant/scene/{scene_name}/activate
if (parts.length !== 4) return null;
if (parts[0] !== "homeassistant") return null;
if (parts[1] !== "scene") return null;
if (parts[3] !== "activate") return null;

const sceneName = parts[2];

// 從 global 中獲取場景配置
const scenes = global.get("scenes") || [];
const scene = scenes.find(s => s.name === sceneName);

if (!scene) {
    node.status({ fill: "red", shape: "ring", text: `場景 ${sceneName} 不存在` });
    return null;
}

// 組 Modbus 指令
let group = scene.group;
if (group === "all" || group === "ALL") {
    group = 0xFF;
}
group = Number(group);

const sceneNum = Number(scene.scene);

if (!Number.isInteger(sceneNum) || sceneNum < 1 || sceneNum > 20) {
    node.status({ fill: "red", shape: "ring", text: "scene 必須是 1~20" });
    return null;
}

if (
    !Number.isInteger(group) ||
    !((group >= 1 && group <= 96) || group === 0xFF)
) {
    node.status({ fill: "red", shape: "ring", text: "group 必須是 1~96 或 ALL" });
    return null;
}

// 組 16-bit VALUE (Set Scene, not Save)
const actionBit = 0; // 0 = Set
const value = (actionBit << 15) | (sceneNum << 8) | group;

const valueHi = (value >> 8) & 0xFF;
const valueLo = value & 0xFF;

msg.payload = Buffer.from([
    0xFE, // Device ID
    0x06, // Function Code
    0x08, // Register High (2080)
    0x20, // Register Low
    valueHi,
    valueLo
]);

node.status({
    fill: "green",
    shape: "dot",
    text: `${scene.display_name} (S${sceneNum} G${group === 0xFF ? "ALL" : group})`
});

return msg;

/**
 * 雙色溫（dual）控制：產生兩筆 Modbus 指令
 * 正確的雙色溫邏輯：亮度決定總輸出，色溫決定冷暖光比例
 * guo 品牌：直接使用 0~255
 * sunwave 品牌：使用 0~100
 */

const DEFAULT_COLORTEMP = 250;  // mired
const MIN_MIRED = 154;
const MAX_MIRED = 370;
const DIMMING_SPEED = 0x05;

const CHANNEL_REGISTER_MAP = {
    a: [0x082A, 0x082B], // cool white, warm white
    b: [0x082C, 0x082D],
};

function buildCommand(slaveId, reg, value) {
    const regHi = (reg >> 8) & 0xFF;
    const regLo = reg & 0xFF;

    return Buffer.from([
        slaveId,
        0x06,
        regHi,
        regLo,
        DIMMING_SPEED,
        value,
    ]);
}

// === Topic 檢查 ===
const parts = String(msg.topic || "").split("/");

if (parts.length !== 6) return null;
if (parts[0] !== "homeassistant") return null;
if (parts[1] !== "light") return null;
if (parts[2] !== "dual") return null;
if (parts[5] !== "set") return null;

const slaveId = Number(parts[3]);
const channel = String(parts[4] || "").toLowerCase();

if (!Number.isInteger(slaveId) || slaveId <= 0) return null;

const regs = CHANNEL_REGISTER_MAP[channel];
if (!regs) return null;

// === 從 device 配置中取得設備資訊 ===
const device = msg.devices.find(d => d.module_id == slaveId && d.channel == channel);
if (!device) return null;

const brightMinimum = device.bright_minimum || 0;
const colortempMinimum = device.colortemp_minimum || MIN_MIRED;
const colortempMaximum = device.colortemp_maximum || MAX_MIRED;
const isGuo = (device.brand === "guo");
const defaultBrightness = isGuo ? 255 : 100;
const maxBrightness = isGuo ? 255 : 100;

// === Payload（只接受 "ON" / "OFF"）===
if (typeof msg.payload !== "string") return null;

const state = msg.payload.toUpperCase();
if (state !== "ON" && state !== "OFF") return null;

const isOn = (state === "ON");

// === 讀取快取 ===
const brKey = `dual_${slaveId}_${channel}_brightness`;
const ctKey = `dual_${slaveId}_${channel}_colortemp`;

let brightness = flow.get(brKey);
if (typeof brightness !== "number") brightness = defaultBrightness;
// 應用最低亮度限制
brightness = Math.max(brightMinimum, brightness);
brightness = Math.min(maxBrightness, brightness);

let colortemp = flow.get(ctKey);
if (typeof colortemp !== "number") colortemp = DEFAULT_COLORTEMP;
// 應用色溫範圍限制
colortemp = Math.min(colortempMaximum, Math.max(colortempMinimum, Math.round(colortemp)));

// === 數值轉換 ===
// 雙色溫燈控制邏輯：
// 1. 色溫決定冷暖光比例
// 2. 亮度決定總輸出功率
// 3. 分別計算冷白光和暖白光的輸出值

// 色溫映射：mired 範圍 → 冷白光比例 (0~1)
// 低 mired (冷色) → 冷白光比例高，暖白光比例低
// 高 mired (暖色) → 冷白光比例低，暖白光比例高
const ctRatio = (colortemp - colortempMinimum) / (colortempMaximum - colortempMinimum);

// 亮度映射
let totalBrightness = isOn ? brightness : 0;
if (isOn) {
    // === 亮度曲線處理（讓低亮度有更多控制精度）===
    let processedBrightness = brightness;
    const curve = device.brightness_curve || "linear";

    if (curve === "square" && brightness > 0) {
        // 平方曲線：低亮度區間有更多階級
        const normalized = brightness / maxBrightness;
        const curved = Math.pow(normalized, 2);
        processedBrightness = Math.round(curved * maxBrightness);
        processedBrightness = Math.max(brightMinimum, processedBrightness);
    }

    // guo 品牌直接使用 0~255，sunwave 需要從 0~100 轉換到 0~255
    if (isGuo) {
        totalBrightness = processedBrightness; // 直接使用 0~255
    } else {
        totalBrightness = Math.round((processedBrightness / 100) * 255); // 0~100 → 0~255
    }
} else {
    totalBrightness = 0;
}
totalBrightness = Math.max(0, Math.min(255, totalBrightness));

// 計算冷白光和暖白光的輸出值
// 冷白光：總亮度 × 冷白光比例
let coolWhiteValue = Math.round(totalBrightness * ctRatio);
// 暖白光：總亮度 × (1 - 冷白光比例)
let warmWhiteValue = Math.round(totalBrightness * (1 - ctRatio));

// 硬體最低閾值：如果值 > 0 但 < 3，燈珠不會亮，需調整為 3
const HARDWARE_MIN = 3;
if (coolWhiteValue > 0 && coolWhiteValue < HARDWARE_MIN) {
    coolWhiteValue = HARDWARE_MIN;
}
if (warmWhiteValue > 0 && warmWhiteValue < HARDWARE_MIN) {
    warmWhiteValue = HARDWARE_MIN;
}

// === 產生兩筆指令 ===
// 第一個寄存器：冷白光輸出
const cmdCoolWhite = buildCommand(slaveId, regs[0], coolWhiteValue);
// 第二個寄存器：暖白光輸出
const cmdWarmWhite = buildCommand(slaveId, regs[1], warmWhiteValue);

node.send({ payload: cmdCoolWhite });
node.send({ payload: cmdWarmWhite });

return null;

// =======================================
// 收到回覆 → 解鎖（基於TCP動態管理）
// =======================================

// 1. 只要是 Buffer，就當作「有回覆」
if (!Buffer.isBuffer(msg.payload)) {
    return null;
}

// 2. 取得TCP標識符，預設為'_default'
const tcpId = msg.tcp || '_default';

// 3. 清掉 timeout（如果還存在）
const timer = flow.get(`currentTimeout${tcpId}`);
if (timer) {
    clearTimeout(timer);
    flow.set(`currentTimeout${tcpId}`, null);
}

// 4. 解鎖對應的TCP連接
global.set(`waitingReply${tcpId}`, false);

// 5. 狀態提示（方便你看流程在跑）
node.status({
    fill: "green",
    shape: "dot",
    text: `收到回覆，解鎖 ${tcpId}`
});

// 6. 主動觸發發送流程，送下一筆
msg.tcp = tcpId; // 確保TCP ID傳遞
return msg;

// =======================================
// 發送流程 + Timeout（基於TCP動態管理）
// =======================================

// 超時時間（ms）
// 建議實務值：600 ~ 1000
const TIMEOUT_MS = 800;

// 1. 取得TCP標識符，預設為'_default'
const tcpId = msg.tcp || '_default';

// 2. 取得對應TCP的佇列
let queue = global.get(`commandsQueue${tcpId}`);
if (!Array.isArray(queue) || queue.length === 0) {
  // 沒指令就什麼都不做
  return null;
}

// 3. 若正在等回覆 → 絕對不能再送
if (global.get(`waitingReply${tcpId}`)) {
  return null;
}

// 4. 取出 FIFO 第一筆
const cmd = queue.shift();
global.set(`commandsQueue${tcpId}`, queue);

// 5. 上鎖（代表「現在有一筆正在飛」）
global.set(`waitingReply${tcpId}`, true);

// 6. 設定 timeout：
//    無論發生什麼事，只要時間到就放行
const timer = setTimeout(() => {

  // 解除鎖定
  global.set(`waitingReply${tcpId}`, false);
  flow.set(`currentTimeout${tcpId}`, null);

  // 顯示狀態（方便現場 debug）
  node.status({
    fill: "yellow",
    shape: "ring",
    text: `timeout 放行 ${tcpId}`
  });

  // 主動觸發自己，再送下一筆
  node.send([null, { _kick: true, tcp: tcpId, reason: "timeout" }]);
}, TIMEOUT_MS);

// 記住 timer，讓「收到回覆」能清掉
flow.set(`currentTimeout${tcpId}`, timer);

// 7. 將指令送到 tcp out
//    注意：這裡只負責送，不關心結果
return { payload: cmd, tcp: tcpId };

initialize:
// 部署節點後，此處添加的代碼將運行一次。 
// 部署初始化：自動清空所有TCP的 queue & 解鎖，避免部署後卡死

// 清理已知的TCP連接
const tcpIds = ['_default', '_tcp1', '_tcp2', '_tcp3'];

tcpIds.forEach(tcpId => {
    global.set(`commandsQueue${tcpId}`, []);
    global.set(`waitingReply${tcpId}`, false);
    flow.set(`currentCmd${tcpId}`, null);
    flow.set(`currentTimeout${tcpId}`, null);
});

// 向下兼容：也清理舊的全局變量
global.set(`commandsQueue`, []);
global.set(`waitingReply`, false);
flow.set(`currentCmd`, null);
flow.set(`currentTimeout`, null);

node.status({ fill: "grey", shape: "ring", text: "部署後已重置所有TCP" });

finalize:
// 節點正在停止或重新部署時，將運行此處添加的代碼。 
// 停止或重新部署時清掉所有TCP的計時器

// 清理已知的TCP連接
const tcpIds = ['_default', '_tcp1', '_tcp2', '_tcp3'];

tcpIds.forEach(tcpId => {
    const t = flow.get(`currentTimeout${tcpId}`);
    if (t) {
        clearTimeout(t);
    }
    flow.set(`currentTimeout${tcpId}`, null);
    global.set(`commandsQueue${tcpId}`, []);
    global.set(`waitingReply${tcpId}`, false);
    flow.set(`currentCmd${tcpId}`, null);
});

// 向下兼容：也清理舊的全局變量
const t = flow.get(`currentTimeout`);
if (t) {
    clearTimeout(t);
}
flow.set(`currentTimeout`, null);
global.set(`commandsQueue`, []);
global.set(`waitingReply`, false);
flow.set(`currentCmd`, null);

