/**
 * S402 4x DI 單擊解析
 *
 * Input:
 *   msg.payload = Buffer(8)
 *   [01, 06, 01, A0, index, flags, crcH, crcL]
 *
 * Output:
 *   msg.topic   = homeassistant/sensor/s402/di
 *   msg.payload = { id, di }
 */

let buf = msg.payload;

if (!Buffer.isBuffer(buf) || buf.length !== 8) return null;

// 解構（CRC 不用）
let [h1, h2, h3, cmd, index, flags] = buf;

// 判斷是否為 S402 DI 4x 封包
if (h1 !== 0x01 || h2 !== 0x06 || h3 !== 0x01 || cmd !== 0xA0) {
    return null;
}

flags &= 0xFF;          // in1 ~ in8
if (flags === 0) return null;

// 單擊事件：取第一個命中的 DI（1~8）
let di = 0;
for (let i = 0; i < 8; i++) {
    if (flags & (1 << i)) {
        di = i + 1;
        break;
    }
}
if (di === 0) return null;

msg.topic = "homeassistant/sensor/s402/di";
msg.payload = {
    id: index,
    di
};

node.status({
    fill: "green",
    shape: "dot",
    text: `s402 id=${index} di=${di}`
});

return msg;

// [01 06 01 A0 03 01 00 00]
msg.payload = Buffer.from([
    0x01, // header
    0x06,
    0x01,
    0xA0, // DI 4x
    0x03, // id = 3
    0x01, // 0000 0001 → DI1
    0x00, // crcH (ignore)
    0x00  // crcL
]);
return msg;

// DI2 + DI5（只會取 DI2）
msg.payload = Buffer.from([
    0x01,
    0x06,
    0x01,
    0xA0,
    0x01,
    0x12, // 0001 0010 → DI2 + DI5
    0x00,
    0x00
]);
return msg;

/**
 * 分流器：根據 msg.devices 中的 model 和 type 分流到對應的解析節點
 * 輸出 1: p404-single
 * 輸出 2: p404-dual
 * 輸出 3: p210-single
 * 輸出 4: p210-dual
 * 輸出 5: sunwave-scene
 * 輸出 6: guo-single
 * 輸出 7: guo-dual
 */

// 防護檢查
if (!msg.payload || !Buffer.isBuffer(msg.payload)) return null;

// === 路由配置 ===
const DEVICE_ROUTES = {
    "p404-single": 0,
    "p404-dual": 1,
    "p210-single": 2,
    "p210-dual": 3,
    "sunwave-scene": 4,
    "p805-single": 5,
    "p805-dual": 6,
};

const SCENE_ROUTE = 4;

// === 工具函數 ===
function isSunwaveScene(buf) {
    return buf.length === 8 && 
           buf[0] === 0xFE && 
           buf[1] === 0x06 && 
           buf[2] === 0x08 && 
           buf[3] === 0x20;
}

function createRouteOutput(targetIndex) {
    const outputs = new Array(7).fill(null);
    outputs[targetIndex] = msg;
    return outputs;
}

// === 場景檢測 ===
if (isSunwaveScene(msg.payload)) {
    return createRouteOutput(SCENE_ROUTE);
}

// === 設備分流邏輯 ===
if (msg.payload.length < 2 || msg.payload[1] !== 0x03) {
    return null; // 只收 Read Holding Registers 回傳
}

const slaveId = msg.payload[0];
const devices = msg.devices || [];
const matchedDevice = devices.find(d => d.module_id == slaveId);

if (!matchedDevice) {
    node.warn(`找不到設備: slaveId=${slaveId}, devices=${JSON.stringify(devices.map(d => ({id: d.module_id, model: d.model, type: d.type})))}`);    
    return null;
}

const deviceKey = `${matchedDevice.model}-${matchedDevice.type}`;
const routeIndex = DEVICE_ROUTES[deviceKey];

if (routeIndex === undefined) {
    node.warn(`找不到路由: deviceKey=${deviceKey}, 可用路由=${Object.keys(DEVICE_ROUTES)}`);
    return null;
}

node.status({ fill: "green", shape: "dot", text: `路由到: ${deviceKey} (輸出${routeIndex + 1})` });
return createRouteOutput(routeIndex);

/**
 * P404 單色溫解析器（0x03 Read Holding Registers）
 * - 從 msg.devices 動態讀取設備配置
 * - 輸出：MQTT 訊息陣列 [{ topic, payload }, ...]
 */

// === Channel 對應 Register 映射（單色溫）===
const CHANNEL_REG_MAP = {
    "1": { brightnessReg: 0 },
    "2": { brightnessReg: 1 },
    "3": { brightnessReg: 2 },
    "4": { brightnessReg: 3 },
};

// === 讀取指定 register 的 Low Byte ===
function readRegLo(frame, regIndex) {
    const dataStart = 3;
    const idx = dataStart + regIndex * 2 + 1;
    if (idx >= frame.length - 2) return null;
    return frame[idx];
}

// ========================= 主程式 =========================
const frame = msg.payload;
if (!Buffer.isBuffer(frame)) return null;
if (frame.length < 5) return null;

const slaveId = frame[0];
const funcCode = frame[1];
const byteCount = frame[2];

if (funcCode !== 0x03) return null;
if (byteCount !== 4 && byteCount !== 8) return null;

const expectedLen = 3 + byteCount + 2;
if (frame.length !== expectedLen) return null;

const regCount = byteCount / 2;
const devices = msg.devices || [];

// 篩選出 P404 單色溫且符合當前 slaveId 的設備
const targetDevices = devices.filter(d => 
    d.model === "p404" && d.type === "single" && d.module_id == slaveId
);

const mqttMsgs = [];

for (const device of targetDevices) {
    const ch = device.channel;
    const info = CHANNEL_REG_MAP[ch];
    if (!info) continue;
    if (info.brightnessReg >= regCount) continue;

    const brightness = readRegLo(frame, info.brightnessReg);
    if (brightness === null) continue;

    const baseTopic = `homeassistant/light/single/${slaveId}/${ch}`;
    const setTopic = `${baseTopic}/set`;

    if (brightness === 0) {
        mqttMsgs.push({ topic: `${baseTopic}/state`, payload: "OFF" });
    } else {
        mqttMsgs.push(
            { topic: `${baseTopic}/state`, payload: "ON" },
            { topic: `${baseTopic}/brightness`, payload: String(brightness) },
            { topic: `${setTopic}/brightness`, payload: String(brightness) }
        );
    }
}

if (mqttMsgs.length === 0) return null;
return [mqttMsgs];

