/**
 * CRC16 驗證過濾器（Modbus）
 * - msg.payload 必須是 Buffer
 * - CRC 正確才往下傳，否則丟棄
 */

const frame = msg.payload;

if (!Buffer.isBuffer(frame)) return null;
if (frame.length < 3) return null; // 至少要有 1 byte 資料 + 2 byte CRC

if (!verifyCrc16Modbus(frame)) return null;

node.status({ fill: "green", shape: "dot", text: "CRC OK" });
msg.source = "feedback"; // 標記來源
return msg;

function verifyCrc16Modbus(buf) {
    const crc = crc16Modbus(buf.slice(0, -2));
    const crcLo = crc & 0xff;
    const crcHi = (crc >> 8) & 0xff;

    return (crcLo === buf[buf.length - 2]) && (crcHi === buf[buf.length - 1]);
}

function crc16Modbus(buf) {
    let crc = 0xffff;

    for (let i = 0; i < buf.length; i++) {
        crc ^= buf[i];

        for (let j = 0; j < 8; j++) {
            if (crc & 0x0001) crc = (crc >> 1) ^ 0xa001;
            else crc >>= 1;
        }
    }

    return crc;
}

