/**
 * Sunwave Scene Event 解析（整合到分流器）
 *
 * Input:
 *   msg.payload = Buffer(8)
 *   [FE, 06, 08, 20, VALUE_H, VALUE_L, CRC_H, CRC_L]
 *
 * Output:
 *   msg.topic   = homeassistant/scene/sunwave/event
 *   msg.payload = { scene: 1~20, group: 1~96 | "all" }
 */

let buf = msg.payload;

if (!Buffer.isBuffer(buf) || buf.length !== 8) return null;

// 解構（CRC 不處理，因為已經在上層驗證過）
let [deviceId, command, addrH, addrL, valueH, valueL] = buf;

// 基本封包判斷（這個檢查在分流器已經做過，但為了安全再檢查一次）
if (
    deviceId !== 0xFE ||
    command  !== 0x06 ||
    addrH    !== 0x08 ||
    addrL    !== 0x20
) {
    return null;
}

