    deviceId !== 0xFE ||
    command  !== 0x06 ||
    addrH    !== 0x08 ||
    addrL    !== 0x20
) {
    return null;
}

// ===== 解析 VALUE =====

// scene: bit[14..8] → valueH 的低 7 bits
let scene = valueH & 0x7F;   // 0b0111_1111

if (scene < 1 || scene > 20) return null;

// group
let group;
if (valueL === 0xFF) {
    group = "all";
} else if (valueL >= 1 && valueL <= 96) {
    group = valueL;
} else {
    return null;
}

msg.topic = "homeassistant/scene/sunwave/event";
msg.payload = { scene, group };

node.status({
    fill: "green",
    shape: "dot",
    text: `scene=${scene}, group=${group}`
});

return msg;

// scene = 3, group = 12
// VALUE_H = 0x03
// VALUE_L = 0x0C

msg.payload = Buffer.from([
    0xFE,
    0x06,
    0x08,
    0x20,
    0x03,
    0x0C,
//    0x00,
//    0x00
]);
return msg;

// scene = 10, group = all (0xFF)

msg.payload = Buffer.from([
    0xFE,
    0x06,
    0x08,
    0x20,
    0x0A,
    0xFF,
    0x00,
    0x00
]);
return msg;

/**
 * CRC Builder - CRC16(Modbus)
 */

const payload = msg.payload;

if (!Buffer.isBuffer(payload)) return null;

const [crcLo, crcHi] = crc16Modbus(payload);

msg.payload = Buffer.concat([payload, Buffer.from([crcLo, crcHi])]);
return msg;

function crc16Modbus(buf) {
    let crc = 0xffff;

    for (let i = 0; i < buf.length; i++) {
        crc ^= buf[i];

        for (let j = 0; j < 8; j++) {
            if (crc & 0x0001) crc = (crc >> 1) ^ 0xa001;
            else crc >>= 1;
        }
    }

    return [crc & 0xff, (crc >> 8) & 0xff];
}

