if (typeof useBrightness !== "number") {
    useBrightness = DEFAULT_BRIGHTNESS;
}

// 應用最低亮度限制
useBrightness = Math.max(brightMinimum, useBrightness);

// 確保輸出落在範圍內（0~255）
useBrightness = Math.max(0, Math.min(255, Math.round(useBrightness)));

