var startAddressHigh = (startAddress >> 8) & 0xFF; // 高位
var startAddressLow = startAddress & 0xFF;        // 低位
var quantityHigh = (quantity >> 8) & 0xFF;        // 高位
var quantityLow = quantity & 0xFF;               // 低位

// 組裝指令
