    functionCode,        // 功能碼
    startAddressHigh,    // 起始地址高位
    startAddressLow,     // 起始地址低位
    quantityHigh,        // 數量高位
    quantityLow          // 數量低位
];

// 計算 CRC 校驗
var crc = calculateCRC(message);
message.push(crc[0]); // CRC 低位
message.push(crc[1]); // CRC 高位

// 將指令存入 msg.payload
msg.payload = Buffer.from(message);
return msg;

// CRC 計算函式
function calculateCRC(data) {
    var crc = 0xFFFF;
    for (var i = 0; i < data.length; i++) {
        crc ^= data[i];
        for (var j = 0; j < 8; j++) {
            if ((crc & 0x0001) !== 0) {
                crc >>= 1;
                crc ^= 0xA001;
            } else {
                crc >>= 1;
            }
        }
    }
    return [crc & 0xFF, (crc >> 8) & 0xFF]; // 返回 CRC 低位和高位
}

// CRC16
function crc16(buf) {
    let crc = 0xFFFF;
    for (const b of buf) {
        crc ^= b;
        for (let i = 0; i < 8; i++) {
            crc = (crc & 1) ? ((crc >> 1) ^ 0xA001) : (crc >> 1);
        }
    }
    return crc;
}

